 "content": "def transform(grid):
    """Extend a solid 2-rectangle toward each border unless a marker blocks that ray."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    if not cells:
        return out
    r0 = min(r for r, _ in cells)
    r1 = max(r for r, _ in cells)
    c0 = min(c for _, c in cells)
    c1 = max(c for _, c in cells)

    # Rays extend from the rectangle to the edge only when that ray is clear.
    for r in range(r0, r1 + 1):
        if all(grid[r][c] in (0, 2) for c in range(c0)):
            for c in range(c0):
                out[r][c] = 2
        if all(grid[r][c] in (0, 2) for c in range(c1 + 1, w)):
            for c in range(c1 + 1, w):
                out[r][c] = 2
    for c in range(c0, c1 + 1):
        if all(grid[r][c] in (0, 2) for r in range(r0)):
            for r in range(r0):
                out[r][c] = 2
        if all(grid[r][c] in (0, 2) for r in range(r1 + 1, h)):
            for r in range(r1 + 1, h):
                out[r][c] = 2
    return out
